{
  "title": "Al-Yamamah Enterprise Employment Application and Terms",
  "planted": [
    {
      "slot": "p1",
      "text": "To evaluate candidacy for the applied position, applicants are strictly required to submit their full national identification card copy, religious affiliation, marital status, exact number of family dependents, and current employer details alongside the standard resume."
    },
    {
      "slot": "p2",
      "text": "The company retains all submitted candidate records and application files indefinitely in our archival database following the conclusion of the recruitment cycle, and reserves the right to store this information permanently for future operational reference."
    },
    {
      "slot": "p3",
      "text": "Applicants maintain the right to be informed of the specific operational purpose for data collection, to access their stored records upon written request, to petition for the correction or update of inaccurate information, and to request the destruction of files that are no longer required for evaluation."
    }
  ],
  "neutral": [
    "All application review fees are strictly non-refundable and must be settled prior to the initial candidate assessment phase through our designated corporate payment gateway.",
    "This application agreement shall commence upon electronic submission by the candidate and shall remain in effect for the duration of the active recruitment window unless terminated earlier by the company.",
    "The company assumes no financial or operational liability for any technical disruptions, transmission delays, or data interception occurrences during the online submission process.",
    "This application procedure and all associated evaluation terms shall be governed by and construed in accordance with the commercial laws applicable within the Kingdom of Saudi Arabia.",
    "For the purposes of this document, Company refers to Al-Yamamah Enterprise, and Applicant refers to the individual submitting their credentials for employment consideration.",
    "All proprietary assessment materials, employer tests, and proprietary evaluation frameworks provided during the application process remain the exclusive intellectual property of the company.",
    "All formal notices, interview schedules, and official communications related to this application shall be delivered electronically to the primary email address provided by the candidate."
  ]
}
